// === Tab: Sketch ===
// By Roni Kaufman
// inspired by https://www.instagram.com/p/B6Rtb0Tnwc3/?igshid=d5co693jh5wy

let nCircles = 50;
let nWaves = 12;
let inter = 10;
let delta;

function setup() {
  createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 100);
  noFill();

  strokeWeight(Math.max(0.1, Math.abs(inter/3)));
  delta = TWO_PI/(4*nWaves);
}

function draw() {
  background(8);

  let size = inter;
  for (let i = 0; i <= nCircles; i++) {
		stroke(53, 84, 94);
		if (i < nCircles*2/5) {
			stroke(16, 100, 100);
		}
    circle(width/2, height/2, size);

    let theta = cos(frameCount/25 - i/5)/10;
    for (let j = 0; j < nWaves*2; j++) {
			if (j < nWaves + 1) {
				if (j % 2 === 0) {
					stroke(60, 74, 64);
				} else {
					stroke(60, 64, 74);
				}
			} else {
				if (j % 2 === 0) {
					stroke(100, 90);
				} else {
					stroke(100, 0);
				}
			}
      arc(width/2, height/2, size, size, 
          theta - delta, theta + delta);
      theta += TWO_PI / (2*nWaves);
    }

    size += inter;

  }
}
